local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum',qemu_args='-d in_asm -D '..root..'producer.log'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',initiator_socket={bind='&apss_router.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    mailbox={moduletype='gs_memory',dmi_allow=false,init_mem=true,
        target_socket={address=0x02000000,size=0x3800,bind='&apss_router.initiator_socket'}},
    software_state={moduletype='qcom,sm8850-tme-software-state-v1',low_reset=0,high_reset=0,handoff_reset=0,
        state_socket={address=0x00c02008,size=8,bind='&apss_router.initiator_socket'},
        update_socket={address=0x00c0022c,size=8,bind='&apss_router.initiator_socket'},
        handoff_socket={address=0x00c02018,size=4,bind='&apss_router.initiator_socket'}},
    status={moduletype='qcom,tme-boot-status-v1',interface_version=0,
        target_socket={address=0x22236000,size=0x50,bind='&apss_router.initiator_socket'},
        mailbox_socket={bind='&mailbox.target_socket'},
        handoff_socket={bind='&handoff_reader.target_socket'}},
    handoff_reader={moduletype='addrtr',mapped_base_addr=0x00c02018,
        target_socket={address=0,size=4,relative_addresses=false},
        initiator_socket={bind='&apss_router.target_socket'}}}
